import { Link } from "@/lib/router-compat";
import { Star, Clock, MapPin, Heart } from "lucide-react";
import type { Restaurant } from "@/types/payplate";
import { Badge } from "@/components/ui/badge";
import { motion } from "framer-motion";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { useState } from "react";
import { cn } from "@/lib/utils";

export function RestaurantCard({ restaurant }: { restaurant: Restaurant }) {
  const reduced = usePrefersReducedMotion();
  const [isFav, setIsFav] = useState(false);

  return (
    <motion.div
      whileHover={!reduced ? { y: -4 } : undefined}
      transition={{ type: "spring", stiffness: 320, damping: 28 }}
      className="h-full"
    >
      <Link
        to={`/restaurants/${restaurant.id}`}
        aria-label={`View ${restaurant.name}`}
        className="block h-full overflow-hidden rounded-2xl border border-border bg-card shadow-card transition-shadow duration-300 hover:shadow-lift"
      >
        {/* Hero image */}
        <div className="relative h-36 overflow-hidden">
          <img
            src={restaurant.heroImage}
            alt={`${restaurant.name} food`}
            className="h-full w-full object-cover transition-transform duration-500 hover:scale-105"
            loading="lazy"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-dark/25 to-transparent" />

          {/* Top badges */}
          <div className="absolute left-2.5 top-2.5 flex gap-1.5">
            {(restaurant.studentDiscountPercent ?? 0) > 0 && (
              <span className="rounded-full bg-primary px-2 py-0.5 text-[10px] font-black text-white shadow-soft">
                {restaurant.studentDiscountPercent}% student
              </span>
            )}
            {restaurant.tags?.includes("Popular") && (
              <span className="rounded-full bg-rewards px-2 py-0.5 text-[10px] font-black text-white shadow-soft">
                Popular
              </span>
            )}
          </div>

          {/* Favourite heart */}
          <button
            onClick={(e) => { e.preventDefault(); setIsFav(!isFav); }}
            aria-label={`Favourite ${restaurant.name}`}
            className="absolute right-2.5 top-2.5 grid size-8 place-items-center rounded-full bg-white/90 backdrop-blur-sm shadow-soft transition-transform active:scale-90"
          >
            <Heart size={15} className={cn("transition-colors", isFav ? "fill-danger text-danger" : "text-muted-foreground")} />
          </button>

          {/* Closed overlay */}
          {!restaurant.isOpen && (
            <div className="absolute inset-0 flex items-center justify-center bg-dark/50 backdrop-blur-[2px]">
              <span className="rounded-full bg-dark/80 px-4 py-1.5 text-sm font-black text-white">Closed</span>
            </div>
          )}
        </div>

        {/* Content */}
        <div className="space-y-1.5 p-3">
          <div className="flex items-start justify-between gap-2">
            <h3 className="truncate font-heading text-base font-black">{restaurant.name}</h3>
            <span className="inline-flex shrink-0 items-center gap-0.5 rounded-full bg-primary/10 px-2 py-0.5 text-xs font-black text-primary">
              <Star size={11} fill="currentColor" />
              {restaurant.rating}
            </span>
          </div>

          <p className="truncate text-xs text-muted-foreground">{restaurant.cuisine}</p>

          {/* Meta row */}
          <div className="flex items-center gap-3 pt-1 text-xs font-bold">
            <span className={cn("inline-flex items-center gap-1", restaurant.isOpen ? "text-primary" : "text-muted-foreground")}>
              <Clock size={13} /> {restaurant.etaMinutes} min
            </span>
            <span className="inline-flex items-center gap-1 text-muted-foreground">
              <MapPin size={13} /> {restaurant.distance}
            </span>
          </div>

          {/* Status tags */}
          <div className="flex flex-wrap items-center gap-1.5 pt-1">
            <span className={cn(
              "rounded-full px-2 py-0.5 text-[10px] font-bold",
              restaurant.isOpen
                ? "bg-success/10 text-success"
                : "bg-danger/10 text-danger",
            )}>
              {restaurant.isOpen ? "Open" : "Closed"}
            </span>
            <span className="rounded-full border border-border px-2 py-0.5 text-[10px] font-bold text-muted-foreground">
              Pickup
            </span>
            <span className="rounded-full border border-border px-2 py-0.5 text-[10px] font-bold text-muted-foreground">
              Delivery
            </span>
          </div>
        </div>
      </Link>
    </motion.div>
  );
}

import { ArrowDownLeft, ArrowUpRight, Gift, RotateCcw } from "lucide-react";
import type { Transaction } from "@/types/payplate";
import { formatRand, timeAgo } from "@/services/payplate-data";
import { cn } from "@/lib/utils";

const iconMap = {
  topup: <ArrowDownLeft size={16} />,
  payment: <ArrowUpRight size={16} />,
  refund: <RotateCcw size={16} />,
  reward: <Gift size={16} />,
};

const colorMap = {
  topup: "bg-success/10 text-success",
  payment: "bg-muted text-muted-foreground",
  refund: "bg-primary/10 text-primary",
  reward: "bg-rewards/10 text-rewards",
};

export function TransactionRow({ transaction }: { transaction: Transaction }) {
  const isPositive = transaction.amountCents > 0;
  return (
    <div className="flex items-center gap-3">
      <div className={cn("grid size-10 place-items-center rounded-xl", colorMap[transaction.type])}>
        {iconMap[transaction.type]}
      </div>
      <div className="min-w-0 flex-1">
        <p className="truncate text-sm font-bold">{transaction.description}</p>
        <p className="text-xs text-muted-foreground">{timeAgo(transaction.date)}</p>
      </div>
      <p className={cn("text-sm font-black tabular-nums", isPositive ? "text-success" : "text-text")}>
        {isPositive ? "+" : ""}{formatRand(transaction.amountCents)}
      </p>
    </div>
  );
}

import type { Transaction } from "@/types/payplate";
import { TransactionRow } from "./transaction-row";

export function TransactionCard({ transaction }: { transaction: Transaction }) {
  return (
    <div className="rounded-2xl border border-border bg-card p-4">
      <TransactionRow transaction={transaction} />
    </div>
  );
}

import type { ReactNode } from "react";
import { motion } from "framer-motion";
import { BottomNav, Sidebar } from "./navigation-bar";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { useLocation } from "@/lib/router-compat";

export function AppShell({ children }: { children: ReactNode }) {
  const reduced = usePrefersReducedMotion();
  const location = useLocation();

  return (
    <div className="min-h-screen">
      <Sidebar />
      <motion.main
        key={location.pathname}
        initial={reduced ? undefined : { opacity: 0, y: 8 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.25, ease: [0.2, 0.9, 0.2, 1] }}
        className="mx-auto w-full max-w-7xl px-5 pb-28 pt-20 lg:ml-64 lg:px-10 lg:pb-12"
      >
        {children}
      </motion.main>
      <BottomNav />
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Wallet } from "lucide-react";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";

const STORAGE_KEY = "payplate_intro_v2";
const FIRST_LAUNCH_KEY = "payplate_first_launch_v2";

// OLED-black brand palette — matches the dark theme tokens exactly
// (--background: #050505, --primary: #00D27A, --accent: #00E5A8)
const BG = "#050505";
const PRIMARY = "#00D27A";
const ACCENT = "#00E5A8";

const TAGLINE_LINES = ["Student Food.", "Smart Payments.", "Real Savings."];

type Phase =
  | "glow"       // 1-2: black bg + ambient glow ramps in
  | "coin"       // 3: 3D coin rotates in
  | "plate"      // 4: coin morphs into a plate
  | "food"       // 5: food elements appear with depth
  | "logo"       // 6: logo fades in
  | "tagline"    // 7: three-line tagline
  | "progress"   // 8: glowing loading bar
  | "wallet"     // 9: plate transitions into wallet icon
  | "out";       // 10: fade into home

const PHASE_TIMINGS: { phase: Phase; at: number }[] = [
  { phase: "glow", at: 0 },
  { phase: "coin", at: 150 },
  { phase: "plate", at: 650 },
  { phase: "food", at: 950 },
  { phase: "logo", at: 1350 },
  { phase: "tagline", at: 1650 },
  { phase: "progress", at: 2050 },
  { phase: "wallet", at: 2450 },
  { phase: "out", at: 2700 },
];

const TOTAL_DURATION = 3000;

export function CinematicSplash({ onComplete }: { onComplete: () => void }) {
  const reduced = usePrefersReducedMotion();
  const [phase, setPhase] = useState<Phase>("glow");
  const [progress, setProgress] = useState(0);
  const doneRef = useRef(false);

  const finish = () => {
    if (doneRef.current) return;
    doneRef.current = true;
    localStorage.setItem(FIRST_LAUNCH_KEY, "done");
    onComplete();
  };

  useEffect(() => {
    // Respect prefers-reduced-motion: skip straight past the animated intro
    if (reduced) {
      finish();
      return;
    }

    const timers = PHASE_TIMINGS.map(({ phase: p, at }) =>
      setTimeout(() => setPhase(p), at)
    );

    // Loading bar fills across the "progress" -> "wallet" window
    const mountedAt = Date.now();
    const progressStart = PHASE_TIMINGS.find((p) => p.phase === "progress")!.at;
    const progressEnd = PHASE_TIMINGS.find((p) => p.phase === "wallet")!.at;
    const progressWindow = progressEnd - progressStart;
    const progressTimer = setInterval(() => {
      const elapsed = Date.now() - mountedAt;
      const pct = Math.min(
        100,
        Math.max(0, ((elapsed - progressStart) / progressWindow) * 100)
      );
      setProgress(pct);
    }, 30);

    const outTimer = setTimeout(finish, TOTAL_DURATION);

    return () => {
      timers.forEach(clearTimeout);
      clearInterval(progressTimer);
      clearTimeout(outTimer);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reduced]);

  const showCoin = phase === "coin";
  const showPlate = phase === "plate" || phase === "food" || phase === "logo" || phase === "tagline" || phase === "progress";
  const showWallet = phase === "wallet";
  const showFood = phase === "food" || phase === "logo" || phase === "tagline" || phase === "progress";
  const showLogo = phase === "logo" || phase === "tagline" || phase === "progress" || phase === "wallet";
  const showTagline = phase === "tagline" || phase === "progress" || phase === "wallet";
  const showProgress = phase === "progress" || phase === "wallet";

  return (
    <motion.div
      exit={{ opacity: 0 }}
      transition={{ duration: 0.5, ease: "easeInOut" }}
      className="fixed inset-0 z-[300] flex flex-col items-center justify-center overflow-hidden"
      style={{ background: BG, willChange: "opacity" }}
    >
      {/* 1-2. OLED black base + soft ambient green glow ramping in */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 1.2, ease: "easeOut" }}
        className="absolute left-1/2 top-1/2 size-[36rem] -translate-x-1/2 -translate-y-1/2 rounded-full"
        style={{
          background: `radial-gradient(circle, ${PRIMARY}33 0%, transparent 70%)`,
          willChange: "opacity",
        }}
      />
      <div
        className="absolute right-[15%] bottom-[20%] size-64 rounded-full blur-[70px]"
        style={{ background: `${ACCENT}22` }}
      />

      {/* Central stage: coin -> plate -> wallet, cross-faded */}
      <div className="relative z-10 flex h-40 items-center justify-center">
        <AnimatePresence mode="wait">
          {showCoin && (
            <motion.div
              key="coin"
              initial={{ scale: 0.3, rotateY: -180, opacity: 0 }}
              animate={{ scale: 1, rotateY: 0, opacity: 1 }}
              exit={{ scale: 0.6, opacity: 0 }}
              transition={{ duration: 0.5, ease: "easeOut" }}
              style={{ transformStyle: "preserve-3d", willChange: "transform, opacity" }}
              className="grid size-28 place-items-center rounded-full text-5xl font-black text-white shadow-2xl"
            >
              <div
                className="grid size-28 place-items-center rounded-full"
                style={{
                  background: `linear-gradient(135deg, ${PRIMARY}, ${ACCENT})`,
                  boxShadow: `0 0 60px ${PRIMARY}73`,
                }}
              >
                P
              </div>
            </motion.div>
          )}

          {showPlate && !showWallet && (
            <motion.div
              key="plate"
              initial={{ scale: 0.7, rotate: -20, opacity: 0 }}
              animate={{ scale: 1, rotate: 0, opacity: 1 }}
              exit={{ scale: 0.7, opacity: 0 }}
              transition={{ duration: 0.5, ease: "easeOut" }}
              style={{ willChange: "transform, opacity" }}
              className="relative grid size-28 place-items-center rounded-full"
            >
              <div
                className="grid size-28 place-items-center rounded-full text-5xl"
                style={{
                  background: `linear-gradient(135deg, ${PRIMARY}, ${ACCENT})`,
                  boxShadow: `0 0 60px ${PRIMARY}73`,
                }}
              >
                🍽️
              </div>

              {/* 5. Food elements orbiting with subtle depth */}
              <AnimatePresence>
                {showFood && (
                  <>
                    <motion.span
                      initial={{ opacity: 0, x: -10, y: -10, scale: 0.5 }}
                      animate={{ opacity: 1, x: -46, y: -36, scale: 1, rotate: [0, -6, 0] }}
                      transition={{ duration: 0.5, rotate: { repeat: Infinity, duration: 2.2 } }}
                      className="absolute text-2xl drop-shadow-lg"
                      style={{ willChange: "transform, opacity" }}
                    >
                      🍔
                    </motion.span>
                    <motion.span
                      initial={{ opacity: 0, x: 10, y: -10, scale: 0.5 }}
                      animate={{ opacity: 1, x: 44, y: -30, scale: 1, rotate: [0, 6, 0] }}
                      transition={{ duration: 0.5, delay: 0.08, rotate: { repeat: Infinity, duration: 2.4 } }}
                      className="absolute text-xl drop-shadow-lg"
                      style={{ willChange: "transform, opacity" }}
                    >
                      🍟
                    </motion.span>
                    <motion.span
                      initial={{ opacity: 0, y: 10, scale: 0.5 }}
                      animate={{ opacity: 1, x: 6, y: 42, scale: 1, rotate: [0, -4, 0] }}
                      transition={{ duration: 0.5, delay: 0.16, rotate: { repeat: Infinity, duration: 2.6 } }}
                      className="absolute text-xl drop-shadow-lg"
                      style={{ willChange: "transform, opacity" }}
                    >
                      🥤
                    </motion.span>
                  </>
                )}
              </AnimatePresence>
            </motion.div>
          )}

          {showWallet && (
            <motion.div
              key="wallet"
              initial={{ scale: 0.6, opacity: 0, rotate: 15 }}
              animate={{ scale: 1, opacity: 1, rotate: 0 }}
              exit={{ scale: 0.8, opacity: 0 }}
              transition={{ duration: 0.45, ease: "easeOut" }}
              style={{ willChange: "transform, opacity" }}
              className="grid size-28 place-items-center rounded-full"
            >
              <div
                className="grid size-28 place-items-center rounded-full"
                style={{
                  background: `linear-gradient(135deg, ${PRIMARY}, ${ACCENT})`,
                  boxShadow: `0 0 60px ${PRIMARY}73`,
                }}
              >
                <Wallet className="size-12 text-white" strokeWidth={2.25} />
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* 6. Logo */}
      <AnimatePresence>
        {showLogo && (
          <motion.h1
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4 }}
            style={{ willChange: "transform, opacity" }}
            className="relative z-10 mt-6 font-heading text-4xl font-black tracking-tight text-white"
          >
            PayPlate
          </motion.h1>
        )}
      </AnimatePresence>

      {/* 7. Three-line tagline */}
      <AnimatePresence>
        {showTagline && (
          <motion.div
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4 }}
            style={{ willChange: "transform, opacity" }}
            className="relative z-10 mt-4 text-center"
          >
            {TAGLINE_LINES.map((line, i) => (
              <motion.p
                key={line}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: i * 0.08, duration: 0.3 }}
                className="text-sm font-bold leading-relaxed"
                style={{ color: i === 2 ? PRIMARY : "#A8A8A8" }}
              >
                {line}
              </motion.p>
            ))}
          </motion.div>
        )}
      </AnimatePresence>

      {/* 8. Glowing loading bar */}
      <AnimatePresence>
        {showProgress && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.25 }}
            className="relative z-10 mt-8 w-44"
          >
            <div className="h-1 overflow-hidden rounded-full" style={{ background: "rgba(255,255,255,0.1)" }}>
              <motion.div
                className="h-full rounded-full"
                style={{
                  width: `${progress}%`,
                  background: `linear-gradient(90deg, ${PRIMARY}, ${ACCENT})`,
                  boxShadow: `0 0 12px ${PRIMARY}`,
                  willChange: "width",
                }}
              />
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

export function QuickSplash({ onComplete }: { onComplete: () => void }) {
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const t = setTimeout(() => {
      localStorage.setItem(STORAGE_KEY, "1");
      onComplete();
    }, reduced ? 0 : 700);
    return () => clearTimeout(t);
  }, [onComplete, reduced]);

  return (
    <motion.div
      exit={{ opacity: 0 }}
      transition={{ duration: 0.3 }}
      className="fixed inset-0 z-[300] flex flex-col items-center justify-center"
      style={{ background: BG }}
    >
      <motion.div
        animate={reduced ? undefined : { scale: [1, 1.06, 1] }}
        transition={{ duration: 0.8, repeat: Infinity }}
        className="grid size-24 place-items-center rounded-full"
        style={{
          background: `linear-gradient(135deg, ${PRIMARY}, ${ACCENT})`,
          boxShadow: `0 0 40px ${PRIMARY}66`,
        }}
      >
        <span className="font-heading text-5xl font-black text-white">P</span>
      </motion.div>
      <p className="mt-5 font-heading text-2xl font-black text-white">PayPlate</p>
    </motion.div>
  );
}

export function SplashWrapper({ children }: { children: React.ReactNode }) {
  const [splashType, setSplashType] = useState<"cinematic" | "quick" | "none" | null>(null);

  useEffect(() => {
    const firstLaunch = !localStorage.getItem(FIRST_LAUNCH_KEY);
    const returning = localStorage.getItem(STORAGE_KEY);
    if (firstLaunch) {
      setSplashType("cinematic");
    } else if (!returning) {
      setSplashType("quick");
    } else {
      setSplashType("none");
    }
  }, []);

  if (splashType === null) return null; // wait for mount

  return (
    <AnimatePresence mode="wait">
      {splashType === "cinematic" && (
        <CinematicSplash key="cinematic" onComplete={() => setSplashType("none")} />
      )}
      {splashType === "quick" && (
        <QuickSplash key="quick" onComplete={() => setSplashType("none")} />
      )}
      {splashType === "none" && (
        <motion.div key="app" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.3 }}>
          {children}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

// Reset splash for testing
export function resetSplash() {
  localStorage.removeItem(STORAGE_KEY);
  localStorage.removeItem(FIRST_LAUNCH_KEY);
}

import { NavLink } from "@/lib/router-compat";
import {
  Home, Receipt, Wallet, Star, User, QrCode,
  type LucideIcon,
} from "lucide-react";
import { useCart } from "@/contexts/cart-context";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { motion } from "framer-motion";
import { cn } from "@/lib/utils";

const NAV_ITEMS: { to: string; label: string; icon: LucideIcon }[] = [
  { to: "/home",      label: "Home",    icon: Home    },
  { to: "/orders",   label: "Orders",  icon: Receipt  },
  { to: "/wallet",   label: "Wallet",  icon: Wallet   },
  { to: "/rewards",  label: "Rewards", icon: Star     },
  { to: "/profile",  label: "Profile", icon: User     },
];

const SIDEBAR_ITEMS
  { to: "/home",          label: "Home",          icon: Home    },
  { to: "/restaurants",   label: "Restaurants",   icon: Home    },
  { to: "/orders",        label: "Orders",        icon: Receipt },
  { to: "/wallet",        label: "Wallet",        icon: Wallet  },
  { to: "/rewards",       label: "Rewards",       icon: Star    },
  { to: "/cart",          label: "Cart",          icon: Receipt },
  { to: "/profile",       label: "Profile",       icon: User    },
  { to: "/notifications", label: "Notifications", icon: Home    },
  { to: "/settings",      label: "Settings",      icon: Home    },
  { to: "/support",       label: "Support",       icon: Home    },
];

/* ─── Bottom Navigation (mobile) ─── */
export function BottomNav() {
  const { itemCount } = useCart();
  const reduced = usePrefersReducedMotion();

  const left  = NAV_ITEMS.slice(0, 2);   // Home, Orders
  const right = NAV_ITEMS.slice(2);      // Wallet, Rewards, Profile

  return (
    <nav
      className="fixed bottom-0 left-0 right-0 z-40 border-t border-border lg:hidden"
      style={{ paddingBottom: "env(safe-area-inset-bottom)", background: "rgba(10,10,10,0.97)", backdropFilter: "blur(20px)" }}
      aria-label="Primary navigation"
    >
      <div className="relative mx-auto flex max-w-md items-end justify-around px-2 pt-2 pb-2">
        {left.map(({ to, label, icon: Icon }) => (
          <NavTab key={to} to={to} label={label} icon={Icon} reduced={reduced}
            badge={to === "/orders" ? itemCount : 0} />
        ))}

        {/* Centre QR FAB */}
        <div className="relative -mt-7 flex w-16 shrink-0 flex-col items-center">
          <NavLink
            to="/wallet"
            aria-label="Scan QR to pay"
            className="relative grid size-16 place-items-center rounded-2xl bg-primary text-white transition-transform active:scale-90"
            style={{ boxShadow: "0 8px 28px rgba(0,210,122,0.45)" }}
          >
            {!reduced && (
              <motion.span
                animate={{ scale: [1, 1.25, 1], opacity: [0.5, 0, 0.5] }}
                transition={{ duration: 2.2, repeat: Infinity, ease: "easeInOut" }}
                className="absolute inset-0 rounded-2xl bg-primary/40"
              />
            )}
            <QrCode size={26} className="relative" />
          </NavLink>
          <span className="mt-0.5 text-[10px] font-bold text-muted-foreground">Pay</span>
        </div>

        {right.map(({ to, label, icon: Icon }) => (
          <NavTab key={to} to={to} label={label} icon={Icon} reduced={reduced} />
        ))}
      </div>
    </nav>
  );
}

function NavTab({
  to, label, icon: Icon, reduced, badge = 0,
}: {
  to: string; label: string; icon: LucideIcon; reduced: boolean; badge?: number;
}) {
  return (
    <NavLink
      to={to}
      className="relative flex flex-1 flex-col items-center gap-0.5 py-1"
      aria-label={label}
    >
      {({ isActive }) => (
        <>
          <span className="relative grid place-items-center">
            {isActive && !reduced && (
              <motion.span
                layoutId="nav-indicator"
                className="absolute -inset-x-3 -inset-y-1.5 rounded-xl bg-primary/12"
                transition={{ type: "spring", stiffness: 400, damping: 32 }}
              />
            )}
            <Icon
              size={22}
              strokeWidth={isActive ? 2.5 : 1.8}
              className={cn("relative transition-colors", isActive ? "text-primary" : "text-muted-foreground")}
            />
            {badge > 0 && (
              <span className="absolute -right-1.5 -top-1 grid min-w-[16px] place-items-center rounded-full bg-primary px-1 text-[9px] font-black text-white">
                {badge}
              </span>
            )}
          </span>
          <span className={cn("relative text-[10px] font-bold transition-colors",
            isActive ? "text-primary" : "text-muted-foreground")}>
            {label}
          </span>
        </>
      )}
    </NavLink>
  );
}

